import numpy as np

def fit_line(x, y):
    x, y = np.array(x, dtype=float), np.array(y, dtype=float)
    if len(x) == 0 or np.all(x == x[0]):
        raise ValueError('x must not be constant')
    dx = x - x.mean()
    w = np.sum(dx * (y - y.mean())) / np.sum(dx * dx)
    return float(w), float(y.mean() - w * x.mean())


def mse(pred, y):
    return float(np.mean((np.array(pred, dtype=float) - np.array(y, dtype=float)) ** 2))


def cross_val_mse(xs, ys, k):
    n = len(xs)
    if not 2 <= k <= n:
        raise ValueError('need 2 <= k <= len(xs)')
    scores = []
    for i in range(k):
        val = list(range(i, n, k))
        train = [j for j in range(n) if j % k != i]
        w, b = fit_line([xs[j] for j in train], [ys[j] for j in train])
        scores.append(mse([w * xs[j] + b for j in val], [ys[j] for j in val]))
    return float(np.mean(scores))

